def reverse_words(sentence):
    words = sentence.split(' ')
    words = words[::-1]
    return ' '.join(words)

print(reverse_words('the quick brown fox'))

def normalize(text, delimiters=None, join_sep=' '):
    if delimiters is None:
        delimiters = [',', ';', '|']
    parts = [text]
    for d in delimiters:
        parts = [p.split(d) for p in parts]
    flat = [item for sublist in parts for item in sublist]
    return join_sep.join(flat)

print(normalize('a,b;c d'))
print(normalize('x|y|z', delimiters=['|'], join_sep=', '))

def normalize_spacing(text):
    tokens = text.split()
    return ' '.join(tokens)

print(normalize_spacing('Hello   world  this   is   Python'))

def reverse_words(text):
    tokens = text.split()
    reversed_tokens = tokens[::-1]
    return ' '.join(reversed_tokens)

print(reverse_words('  the   sky is blue  '))
